"""CSV 读取与类型推断。

实现 docs/FORMAT_SPEC.md 的全部要求：
- 自动识别 UTF-8（含 BOM）/ UTF-16 LE/BE（含 BOM）/ GBK
- 支持引号包裹（逗号、换行、回车作为字段内容）与双引号转义
- 空值 / NULL / 引号空串的区分
- int / float / date / bool 类型推断（前导零与科学计数法保留为字符串）
- 列数结构校验（错误带行号）与 skip_bad 容错模式
- iter_csv 流式产出，不把整个文件读入内存
仅使用标准库。
"""

import io
import re
from datetime import date
from pathlib import Path

# 读编码嗅探块与流式缓冲区的大小（64 KiB）
_SNIFF_BYTES = 65536
_READ_CHARS = 65536


class FormatError(Exception):
    """CSV 结构不合法（列数不一致、引号未闭合等）。"""


class DecodeError(Exception):
    """文件编码无法识别或解码失败。"""


# --------------------------------------------------------------------------
# 编码识别
# --------------------------------------------------------------------------
def _open_text(path: Path) -> io.TextIOBase:
    """按 BOM / 内容嗅探编码，返回逐块解码的文本流。

    识别顺序：UTF-16 BOM -> UTF-8 BOM/严格 UTF-8 -> GBK，全部失败抛 DecodeError。
    全程只读开头一小块，不把整个文件载入内存。
    """
    raw = open(path, "rb")
    try:
        head = raw.read(_SNIFF_BYTES)
    except BaseException:
        raw.close()
        raise

    if not head:
        # 空文件：给一个空的 UTF-8 文本流即可
        raw.close()
        return io.StringIO("")

    # UTF-16 必须带 BOM（规范第 1 条）
    if head.startswith(b"\xff\xfe"):
        encoding = "utf-16-le"
        bom_len = 2
    elif head.startswith(b"\xfe\xff"):
        encoding = "utf-16-be"
        bom_len = 2
    elif head.startswith(b"\xef\xbb\xbf"):
        encoding = "utf-8-sig"  # 自动消费 BOM
        bom_len = 0
    else:
        bom_len = 0
        try:
            head.decode("utf-8")
            encoding = "utf-8"
        except UnicodeDecodeError:
            try:
                head.decode("gbk")
                encoding = "gbk"
            except UnicodeDecodeError as exc:
                raw.close()
                raise DecodeError(
                    f"无法识别文件编码：既不是合法 UTF-8 也不是 GBK（{exc}）"
                ) from exc

    raw.seek(0)
    if bom_len:
        raw.read(bom_len)  # 手工跳过 BOM，避免 TextIOWrapper 残留
    return io.TextIOWrapper(raw, encoding=encoding, errors="strict", newline="")


# --------------------------------------------------------------------------
# 词法解析：把文本流切成 (字段, 是否被引号包裹) 与记录结束标记
# --------------------------------------------------------------------------
def _tokenize(text: io.TextIOBase):
    """逐字符状态机，产出 (kind, value, physical_line)。

    kind 为 "field"（value 是 (text, quoted)）或 "eorec"（记录结束）。
    引号内的逗号/\\r/\\n 都是字段内容；"" 转义为单个 "。
    行号 physical_line 按物理换行统计，从 1 开始。
    """
    state = 0          # 0=字段开头/普通, 1=普通字符中, 2=引号内, 3=引号内遇引号
    field_chars: list[str] = []
    quoted = False
    line_no = 1
    field_start_line = 1
    pending_cr = False  # 引号内 \\r 已入字段，需与后续 \\n 合并为 \\r\\n

    def emit_field():
        return (
            "field",
            ("".join(field_chars), quoted),
            field_start_line,
        )

    while True:
        chunk = text.read(_READ_CHARS)
        if not chunk:
            break
        for ch in chunk:
            if pending_cr and ch != "\n":
                pending_cr = False

            if state == 0:
                if ch == '"':
                    quoted = True
                    state = 2
                elif ch == ",":
                    yield emit_field()
                    field_chars = []
                    quoted = False
                    field_start_line = line_no
                elif ch == "\r":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    line_no += 1
                    field_chars = []
                    quoted = False
                    state = 4  # 吞掉可能的 \n
                    field_start_line = line_no
                elif ch == "\n":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    field_chars = []
                    quoted = False
                    field_start_line = line_no
                else:
                    field_chars.append(ch)
                    state = 1
            elif state == 1:
                if ch == ",":
                    yield emit_field()
                    field_chars = []
                    quoted = False
                    state = 0
                    field_start_line = line_no
                elif ch == "\r":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    line_no += 1
                    field_chars = []
                    quoted = False
                    state = 4
                    field_start_line = line_no
                elif ch == "\n":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    field_chars = []
                    quoted = False
                    state = 0
                    field_start_line = line_no
                else:
                    field_chars.append(ch)
            elif state == 2:
                if ch == '"':
                    state = 3
                else:
                    if ch == "\r":
                        field_chars.append("\r")
                        pending_cr = True
                        line_no += 1
                    elif ch == "\n":
                        if not pending_cr:
                            field_chars.append("\n")
                        pending_cr = False
                        line_no += 1
                    else:
                        field_chars.append(ch)
            elif state == 3:
                if ch == '"':  # 转义引号 ""
                    field_chars.append('"')
                    state = 2
                elif ch == ",":
                    yield emit_field()
                    field_chars = []
                    quoted = False
                    state = 0
                    field_start_line = line_no
                elif ch == "\r":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    line_no += 1
                    field_chars = []
                    quoted = False
                    state = 4
                    field_start_line = line_no
                elif ch == "\n":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    field_chars = []
                    quoted = False
                    state = 0
                    field_start_line = line_no
                else:
                    # 引号闭合后又出现普通字符，属于非法 CSV
                    raise FormatError(
                        f"第 {line_no} 行：引号闭合后出现多余字符 {ch!r}"
                    )
            else:  # state == 4：\r 之后，吞掉配对的 \n
                state = 0
                if ch == "\n":
                    continue
                # 不是 \n，回退普通分支重新处理当前字符
                if ch == '"':
                    quoted = True
                    state = 2
                elif ch == ",":
                    yield emit_field()
                    field_chars = []
                    quoted = False
                    field_start_line = line_no
                elif ch == "\r":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    line_no += 1
                    field_chars = []
                    state = 4
                    field_start_line = line_no
                elif ch == "\n":
                    yield emit_field()
                    yield ("eorec", None, line_no)
                    field_chars = []
                    field_start_line = line_no
                else:
                    field_chars.append(ch)
                    state = 1

    # EOF：仍在引号内 => 未闭合
    if state == 2:
        raise FormatError(f"第 {line_no} 行：引号未闭合")
    if state in (0, 1, 3):
        # 最后一行没有末尾换行，也要产出；state==0 且无内容则不产出空记录
        if state != 0 or field_chars or quoted:
            yield emit_field()
            yield ("eorec", None, line_no)


def _iter_records(path: str | Path):
    """把 token 聚合成记录，逐行产出 (行号, [字段], [quoted 标记])。

    跳过纯空行（零字段记录）。行号为物理行号，表头为第 1 行。
    解码错误统一包装为 DecodeError。
    """
    text = _open_text(Path(path))
    try:
        fields: list[str] = []
        flags: list[bool] = []
        record_line = 1
        try:
            for kind, value, line_no in _tokenize(text):
                if kind == "field":
                    if not fields:
                        record_line = line_no
                    cell, quoted = value
                    fields.append(cell)
                    flags.append(quoted)
                else:  # eorec
                    if fields:
                        yield record_line, fields, flags
                    fields = []
                    flags = []
        except UnicodeDecodeError as exc:
            raise DecodeError(f"文件解码失败：{exc}") from exc
    finally:
        text.close()


# --------------------------------------------------------------------------
# 类型推断
# --------------------------------------------------------------------------
_INT_RE = re.compile(r"-?\d+$")
_FLOAT_RE = re.compile(r"-?\d+\.\d+$")
_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}$")


def _infer(text: str, quoted: bool):
    """对单个字段做类型推断（规范第 3、4 条）。"""
    if not quoted:
        if text == "":
            return None  # 完全空字段 ,,
        if text.upper() == "NULL":
            return None  # NULL 大小写不敏感（仅限未加引号的裸字段）
    if quoted:
        if text == "":
            return ""  # "" 显式空字符串

    low = text.lower()
    if low == "true":
        return True
    if low == "false":
        return False
    if _INT_RE.match(text):
        # 前导零保留为字符串：007 / 0123；单独的 0 仍是 int
        if len(text) > 1 and text.lstrip("-")[:1] == "0":
            return text
        return int(text)
    if _FLOAT_RE.match(text):
        return float(text)  # 科学计数法 1e5 不匹配，保持字符串
    if _DATE_RE.match(text):
        try:
            return date.fromisoformat(text)
        except ValueError:
            return text
    return text  # 其他形态保持原样，不去空格


def _build_row(header: list[str], fields: list[str], flags: list[bool]) -> dict:
    return {
        name: _infer(cell, quoted)
        for name, cell, quoted in zip(header, fields, flags)
    }


# --------------------------------------------------------------------------
# 对外 API
# --------------------------------------------------------------------------
def _header_and_rows(path: str | Path):
    """生成 (header, 后续记录生成器)；供 read_csv / iter_csv 共用。"""
    records = _iter_records(path)
    try:
        _, header_fields, header_flags = next(records)
    except StopIteration:
        return [], iter(())
    header = [_infer(cell, quoted) if quoted else cell
              for cell, quoted in zip(header_fields, header_flags)]
    return header, records


def iter_csv(path: str | Path):
    """逐行产出 dict 的流式读取器，不把整个文件读进内存。

    严格模式：列数不齐抛带行号的 FormatError。
    """
    header, records = _header_and_rows(path)
    if not header:
        return
    width = len(header)
    for line_no, fields, flags in records:
        if len(fields) != width:
            raise FormatError(
                f"第 {line_no} 行列数为 {len(fields)}，与表头列数 {width} 不一致"
            )
        yield _build_row(header, fields, flags)


def read_csv(path: str | Path, skip_bad: bool = False):
    """读取整个 CSV。

    默认严格模式，返回 list[dict]；skip_bad=True 时跳过坏行，
    返回 (rows, stats)，stats 含 total / skipped / errors。
    """
    header, records = _header_and_rows(path)
    if not header:
        if skip_bad:
            return [], {"total": 0, "skipped": 0, "errors": []}
        return []

    width = len(header)

    if not skip_bad:
        rows = []
        for line_no, fields, flags in records:
            if len(fields) != width:
                raise FormatError(
                    f"第 {line_no} 行列数为 {len(fields)}，与表头列数 {width} 不一致"
                )
            rows.append(_build_row(header, fields, flags))
        return rows

    rows = []
    total = 0
    skipped = 0
    errors = []
    for line_no, fields, flags in records:
        total += 1
        if len(fields) != width:
            skipped += 1
            errors.append((
                line_no,
                f"列数为 {len(fields)}，与表头列数 {width} 不一致",
            ))
            continue
        try:
            rows.append(_build_row(header, fields, flags))
        except FormatError as exc:
            skipped += 1
            errors.append((line_no, str(exc)))
    return rows, {"total": total, "skipped": skipped, "errors": errors}

