            yield ("eorec", None, line_no)


def _iter_records(path: str | Path):
    """把 token 聚合成记录，逐行产出 (行号, [字段], [quoted 标记])。

    跳过纯空行（零字段记录）。行号为物理行号，表头为第 1 行。
    解码错误统一包装为 DecodeError。
    """
    text = _open_text(Path(path))
    try:
        fields: list[str] = []
        flags: list[bool] = []
        record_line = 1
        try:
            for kind, value, line_no in _tokenize(text):
                if kind == "field":
                    if not fields:
                        record_line = line_no
                    cell, quoted = value
                    fields.append(cell)
                    flags.append(quoted)
                else:  # eorec
                    if fields:
                        yield record_line, fields, flags
                    fields = []
                    flags = []
        except UnicodeDecodeError as exc:
            raise DecodeError(f"文件解码失败：{exc}") from exc
    finally:
        text.close()


