    rows = []
    total = 0
    skipped = 0
    errors = []
    for line_no, fields, flags in records:
        total += 1
        if len(fields) != width:
            skipped += 1
            errors.append((
                line_no,
                f"列数为 {len(fields)}，与表头列数 {width} 不一致",
            ))
